"""Async WebSocket notification server with a small health endpoint."""

from __future__ import annotations

import asyncio
import json
import os
import sqlite3
import threading
import uuid
from datetime import datetime, timezone
from typing import Any
from urllib.parse import parse_qs, urlparse

from aiohttp import web
from redis.asyncio import Redis
from websockets.asyncio.server import ServerConnection, serve


SUPPORTED_TYPES = {"broadcast", "direct", "system", "subscribe", "unsubscribe"}
REDIS_CHANNEL = "notification-server:messages"


def _timestamp() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _message(message_type: str, payload: dict[str, Any]) -> dict[str, Any]:
    return {"type": message_type, "payload": payload, "timestamp": _timestamp()}


class ClientRegistry:
    """A client registry safe to access from event-loop and worker threads."""

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._clients: dict[str, ServerConnection] = {}
        self._subscriptions: dict[str, set[str]] = {}

    def add(self, connection: ServerConnection, client_id: str | None = None) -> str:
        client_id = client_id or str(uuid.uuid4())
        with self._lock:
            self._clients[client_id] = connection
        return client_id

    def remove(self, client_id: str) -> None:
        with self._lock:
            self._clients.pop(client_id, None)
            for channel in list(self._subscriptions):
                subscribers = self._subscriptions[channel]
                subscribers.discard(client_id)
                if not subscribers:
                    del self._subscriptions[channel]

    def subscribe(self, client_id: str, channel: str) -> None:
        with self._lock:
            self._subscriptions.setdefault(channel, set()).add(client_id)

    def unsubscribe(self, client_id: str, channel: str) -> None:
        with self._lock:
            subscribers = self._subscriptions.get(channel)
            if subscribers is None:
                return
            subscribers.discard(client_id)
            if not subscribers:
                del self._subscriptions[channel]

    def channel_snapshot(self) -> dict[str, list[str]]:
        with self._lock:
            return {
                channel: sorted(client_ids)
                for channel, client_ids in self._subscriptions.items()
                if client_ids
            }

    def get(self, client_id: str) -> ServerConnection | None:
        with self._lock:
            return self._clients.get(client_id)

    def snapshot(self) -> dict[str, ServerConnection]:
        with self._lock:
            return dict(self._clients)

    def __len__(self) -> int:
        with self._lock:
            return len(self._clients)


class MessageStore:
    """Small SQLite store shared by the HTTP history endpoint and publisher."""

    def __init__(self, database_url: str | None = None) -> None:
        self.path = database_url or os.environ.get("DATABASE_URL", "messages.db")
        if self.path.startswith("sqlite:///"):
            self.path = self.path[10:]
        with self._connect() as connection:
            connection.execute(
                "CREATE TABLE IF NOT EXISTS messages ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                "channel TEXT, type TEXT NOT NULL, payload TEXT NOT NULL, "
                "timestamp TEXT NOT NULL)"
            )

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.path)
        connection.row_factory = sqlite3.Row
        return connection

    def add(self, message: dict[str, Any]) -> None:
        payload = message["payload"]
        channel = payload.get("channel") if isinstance(payload, dict) else None
        with self._connect() as connection:
            connection.execute(
                "INSERT INTO messages (channel, type, payload, timestamp) VALUES (?, ?, ?, ?)",
                (channel, message["type"], json.dumps(payload), message["timestamp"]),
            )

    def list(self, limit: int, offset: int) -> list[dict[str, Any]]:
        with self._connect() as connection:
            rows = connection.execute(
                "SELECT id, channel, type, payload, timestamp FROM messages "
                "ORDER BY id DESC LIMIT ? OFFSET ?", (limit, offset)
            ).fetchall()
        return [
            {"id": row["id"], "channel": row["channel"], "type": row["type"],
             "payload": json.loads(row["payload"]), "timestamp": row["timestamp"]}
            for row in rows
        ]


class RedisBackbone:
    """Redis transport and durable client subscription state."""

    def __init__(self, url: str) -> None:
        self.redis = Redis.from_url(url, decode_responses=True)
        self.pubsub = self.redis.pubsub()
        self.task: asyncio.Task[None] | None = None
        self.on_message = None

    async def start(self, on_message) -> None:
        await self.redis.ping()
        self.on_message = on_message
        await self.pubsub.subscribe(REDIS_CHANNEL)
        self.task = asyncio.create_task(self._listen())

    async def _listen(self) -> None:
        async for item in self.pubsub.listen():
            if item["type"] == "message" and self.on_message is not None:
                await self.on_message(json.loads(item["data"]))

    async def publish(self, message: dict[str, Any]) -> None:
        await self.redis.publish(REDIS_CHANNEL, json.dumps(message))

    async def save_client(self, client_id: str) -> None:
        await self.redis.hset(f"notification:client:{client_id}", mapping={"active": "1"})

    async def add_subscription(self, client_id: str, channel: str) -> None:
        await self.redis.sadd(f"notification:subscriptions:{client_id}", channel)

    async def remove_subscription(self, client_id: str, channel: str) -> None:
        await self.redis.srem(f"notification:subscriptions:{client_id}", channel)

    async def subscriptions(self, client_id: str) -> set[str]:
        return set(await self.redis.smembers(f"notification:subscriptions:{client_id}"))

    async def close(self) -> None:
        await self.pubsub.close()
        if self.task:
            self.task.cancel()
            await asyncio.gather(self.task, return_exceptions=True)
        await self.redis.close()


class NotificationServer:
    """Run the WebSocket and HTTP health services on the current event loop."""

    def __init__(self, host: str = "127.0.0.1", websocket_port: int = 8765,
                 health_port: int = 8080, redis_url: str | None = None,
                 database_url: str | None = None) -> None:
        self.host = host
        self.websocket_port = websocket_port
        self.health_port = health_port
        self.clients = ClientRegistry()
        self.store = MessageStore(database_url)
        self.redis_url = redis_url or os.environ.get("REDIS_URL")
        self.backbone: RedisBackbone | None = None
        self._websocket_server = None
        self._http_runner: web.AppRunner | None = None
        self._health_site: web.TCPSite | None = None

    async def start(self) -> "NotificationServer":
        if self.redis_url:
            candidate = RedisBackbone(self.redis_url)
            try:
                await candidate.start(self._receive_published)
                self.backbone = candidate
            except Exception:
                await candidate.close()
        self._websocket_server = await serve(
            self._handle_connection, self.host, self.websocket_port
        )
        websocket_socket = self._websocket_server.sockets[0]
        self.websocket_port = websocket_socket.getsockname()[1]

        app = web.Application()
        app.router.add_get("/health", self._health)
        app.router.add_get("/channels", self._channels)
        app.router.add_get("/channels/{name}/subscribers", self._channel_subscribers)
        app.router.add_get("/messages", self._messages)
        self._http_runner = web.AppRunner(app)
        await self._http_runner.setup()
        self._health_site = web.TCPSite(
            self._http_runner, self.host, self.health_port
        )
        await self._health_site.start()
        if self._health_site._server and self._health_site._server.sockets:
            self.health_port = self._health_site._server.sockets[0].getsockname()[1]
        return self

    async def stop(self) -> None:
        if self._websocket_server is not None:
            self._websocket_server.close()
            await self._websocket_server.wait_closed()
            self._websocket_server = None
        if self._http_runner is not None:
            await self._http_runner.cleanup()
            self._http_runner = None
        if self.backbone is not None:
            await self.backbone.close()
            self.backbone = None

    async def _health(self, request: web.Request) -> web.Response:
        return web.json_response({"connected_clients": len(self.clients)})

    async def _channels(self, request: web.Request) -> web.Response:
        channels = self.clients.channel_snapshot()
        return web.json_response({
            "channels": [
                {"name": name, "subscriber_count": len(subscribers)}
                for name, subscribers in sorted(channels.items())
            ]
        })

    async def _channel_subscribers(self, request: web.Request) -> web.Response:
        channel = request.match_info["name"]
        subscribers = self.clients.channel_snapshot().get(channel, [])
        return web.json_response({"subscribers": subscribers})

    async def _messages(self, request: web.Request) -> web.Response:
        try:
            limit = int(request.query.get("limit", "50"))
            offset = int(request.query.get("offset", "0"))
            if limit < 1 or limit > 1000 or offset < 0:
                raise ValueError
        except ValueError:
            return web.json_response({"error": "limit must be 1..1000 and offset must be non-negative"}, status=400)
        return web.json_response(await asyncio.to_thread(self.store.list, limit, offset))

    async def _handle_connection(self, connection: ServerConnection) -> None:
        path = getattr(getattr(connection, "request", None), "path", "")
        requested_id = parse_qs(urlparse(path).query).get("client_id", [None])[0]
        client_id = self.clients.add(connection, requested_id)
        if self.backbone:
            await self.backbone.save_client(client_id)
            for channel in await self.backbone.subscriptions(client_id):
                self.clients.subscribe(client_id, channel)
        try:
            await connection.send(json.dumps(_message("system", {
                "event": "connected", "client_id": client_id
            })))
            async for raw_message in connection:
                await self._handle_message(client_id, raw_message)
        finally:
            self.clients.remove(client_id)

    async def _handle_message(self, sender_id: str, raw_message: str) -> None:
        try:
            incoming = json.loads(raw_message)
            message_type = incoming.get("type")
            payload = incoming.get("payload")
            if message_type not in SUPPORTED_TYPES or not isinstance(payload, dict):
                raise ValueError("type must be supported and payload must be an object")
            channel = payload.get("channel")
            if message_type in {"subscribe", "unsubscribe"} and not self._valid_channel(channel):
                raise ValueError("subscription messages require payload.channel")
        except (json.JSONDecodeError, AttributeError, TypeError, ValueError) as exc:
            await self._send_to(sender_id, _message("system", {"error": str(exc)}))
            return

        if message_type == "subscribe":
            self.clients.subscribe(sender_id, channel)
            if self.backbone:
                await self.backbone.add_subscription(sender_id, channel)
            return
        if message_type == "unsubscribe":
            self.clients.unsubscribe(sender_id, channel)
            if self.backbone:
                await self.backbone.remove_subscription(sender_id, channel)
            return

        outgoing = _message(message_type, payload)
        if message_type == "direct" and not self._valid_channel(payload.get("channel")):
            recipient_id = payload.get("recipient_id", payload.get("client_id"))
            if not isinstance(recipient_id, str):
                await self._send_to(sender_id, _message("system", {
                    "error": "direct messages require payload.recipient_id"
                }))
                return
            outgoing["_recipient_id"] = recipient_id
        self.store.add(outgoing)
        if self.backbone:
            await self.backbone.publish(outgoing)
        else:
            await self._receive_published(outgoing)

    async def _receive_published(self, message: dict[str, Any]) -> None:
        recipient_id = message.get("_recipient_id")
        payload = message.get("payload", {})
        delivered = {key: value for key, value in message.items() if key != "_recipient_id"}
        if recipient_id:
            await self._send_connection(self.clients.get(recipient_id), delivered)
        elif self._valid_channel(payload.get("channel")):
            await self._broadcast_channel(payload["channel"], delivered)
        else:
            await self._broadcast(delivered)

    @staticmethod
    def _valid_channel(channel: Any) -> bool:
        return isinstance(channel, str) and bool(channel.strip())

    async def _broadcast_channel(self, channel: str, message: dict[str, Any]) -> None:
        subscribers = self.clients.channel_snapshot().get(channel, [])
        await asyncio.gather(*(
            self._send_connection(self.clients.get(client_id), message)
            for client_id in subscribers
        ))

    async def _broadcast(self, message: dict[str, Any]) -> None:
        await asyncio.gather(*(
            self._send_connection(connection, message)
            for connection in self.clients.snapshot().values()
        ))

    async def _send_to(self, client_id: str, message: dict[str, Any]) -> None:
        await self._send_connection(self.clients.get(client_id), message)

    async def _send_connection(self, connection: ServerConnection | None,
                                message: dict[str, Any]) -> None:
        if connection is not None:
            try:
                await connection.send(json.dumps(message))
            except Exception:
                # A connection can close between taking the registry snapshot and send.
                pass

    async def run_forever(self) -> None:
        await self.start()
        try:
            await asyncio.Future()
        finally:
            await self.stop()


async def main() -> None:
    server = NotificationServer()
    await server.run_forever()


if __name__ == "__main__":
    asyncio.run(main())

import json
import asyncio

import aiohttp
import pytest
from redis.asyncio import Redis
from websockets.asyncio.client import connect

from notification_server import NotificationServer


@pytest.fixture
async def server(tmp_path):
    instance = NotificationServer(
        websocket_port=0, health_port=0,
        database_url=str(tmp_path / "messages.db"),
    )
    await instance.start()
    yield instance
    await instance.stop()


async def receive_json(socket):
    return json.loads(await socket.recv())


@pytest.mark.asyncio
async def test_assigns_ids_broadcasts_and_reports_health(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as first, connect(url) as second:
        first_connected = await receive_json(first)
        second_connected = await receive_json(second)
        assert first_connected["type"] == "system"
        assert first_connected["payload"]["client_id"] != second_connected["payload"]["client_id"]

        async with aiohttp.ClientSession() as session:
            async with session.get(
                f"http://{server.host}:{server.health_port}/health"
            ) as response:
                assert response.status == 200
                assert await response.json() == {"connected_clients": 2}

        await first.send(json.dumps({"type": "broadcast", "payload": {"text": "hello"}}))
        assert (await receive_json(first))["payload"] == {"text": "hello"}
        assert (await receive_json(second))["payload"] == {"text": "hello"}

    async with aiohttp.ClientSession() as session:
        async with session.get(f"http://{server.host}:{server.health_port}/health") as response:
            assert (await response.json())["connected_clients"] == 0


@pytest.mark.asyncio
async def test_direct_message_only_reaches_recipient(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as sender, connect(url) as recipient:
        sender_info = await receive_json(sender)
        recipient_info = await receive_json(recipient)
        await sender.send(json.dumps({
            "type": "direct",
            "payload": {"recipient_id": recipient_info["payload"]["client_id"], "value": 3},
        }))
        assert (await receive_json(recipient))["payload"]["value"] == 3
        with pytest.raises(asyncio.TimeoutError):
            await asyncio.wait_for(recipient.recv(), timeout=0.05)


@pytest.mark.asyncio
async def test_rejects_invalid_messages_with_system_error(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as socket:
        await receive_json(socket)
        await socket.send("not json")
        response = await receive_json(socket)
        assert response["type"] == "system"
        assert "error" in response["payload"]


@pytest.mark.asyncio
async def test_channel_messages_only_reach_subscribers_and_can_unsubscribe(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as alerts_client, connect(url) as other_client:
        alerts_info = await receive_json(alerts_client)
        await receive_json(other_client)
        channel = "alerts"

        await alerts_client.send(json.dumps({
            "type": "subscribe", "payload": {"channel": channel}
        }))
        await alerts_client.send(json.dumps({
            "type": "broadcast",
            "payload": {"channel": channel, "text": "first"},
        }))
        assert (await receive_json(alerts_client))["payload"]["text"] == "first"
        with pytest.raises(asyncio.TimeoutError):
            await asyncio.wait_for(other_client.recv(), timeout=0.05)

        await alerts_client.send(json.dumps({
            "type": "unsubscribe", "payload": {"channel": channel}
        }))
        await alerts_client.send(json.dumps({
            "type": "broadcast",
            "payload": {"channel": channel, "text": "second"},
        }))
        with pytest.raises(asyncio.TimeoutError):
            await asyncio.wait_for(alerts_client.recv(), timeout=0.05)

        async with aiohttp.ClientSession() as session:
            async with session.get(
                f"http://{server.host}:{server.health_port}/channels"
            ) as response:
                assert await response.json() == {"channels": []}
            async with session.get(
                f"http://{server.host}:{server.health_port}/channels/{channel}/subscribers"
            ) as response:
                assert await response.json() == {"subscribers": []}


@pytest.mark.asyncio
async def test_multiple_channel_subscriptions_and_channel_rest_listing(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as first, connect(url) as second:
        first_id = (await receive_json(first))["payload"]["client_id"]
        second_id = (await receive_json(second))["payload"]["client_id"]
        for channel in ("alerts", "system"):
            await first.send(json.dumps({
                "type": "subscribe", "payload": {"channel": channel}
            }))
        await second.send(json.dumps({
            "type": "subscribe", "payload": {"channel": "alerts"}
        }))

        async with aiohttp.ClientSession() as session:
            async with session.get(
                f"http://{server.host}:{server.health_port}/channels"
            ) as response:
                assert await response.json() == {"channels": [
                    {"name": "alerts", "subscriber_count": 2},
                    {"name": "system", "subscriber_count": 1},
                ]}
            async with session.get(
                f"http://{server.host}:{server.health_port}/channels/alerts/subscribers"
            ) as response:
                assert (await response.json())["subscribers"] == sorted(
                    [first_id, second_id]
                )


@pytest.mark.asyncio
async def test_messages_are_persisted_and_paginated(server):
    url = f"ws://{server.host}:{server.websocket_port}"
    async with connect(url) as socket:
        await receive_json(socket)
        await socket.send(json.dumps({
            "type": "subscribe", "payload": {"channel": "history"}
        }))
        await socket.send(json.dumps({
            "type": "broadcast", "payload": {"channel": "history", "value": 1}
        }))
        assert (await receive_json(socket))["payload"]["value"] == 1

    async with aiohttp.ClientSession() as session:
        async with session.get(
            f"http://{server.host}:{server.health_port}/messages?limit=1&offset=0"
        ) as response:
            messages = await response.json()
    assert len(messages) == 1
    assert messages[0]["channel"] == "history"
    assert messages[0]["type"] == "broadcast"
    assert messages[0]["payload"]["value"] == 1


@pytest.mark.asyncio
async def test_redis_backbone_delivers_between_server_instances(tmp_path):
    redis = Redis.from_url("redis://127.0.0.1:6379", decode_responses=True)
    try:
        await redis.ping()
    except Exception:
        await redis.close()
        pytest.skip("Redis is not running")
    await redis.flushdb()
    first = NotificationServer(
        websocket_port=0, health_port=0, redis_url="redis://127.0.0.1:6379",
        database_url=str(tmp_path / "messages.db"),
    )
    second = NotificationServer(
        websocket_port=0, health_port=0, redis_url="redis://127.0.0.1:6379",
        database_url=str(tmp_path / "messages.db"),
    )
    await first.start()
    await second.start()
    try:
        async with connect(f"ws://{second.host}:{second.websocket_port}") as subscriber:
            await receive_json(subscriber)
            await subscriber.send(json.dumps({
                "type": "subscribe", "payload": {"channel": "shared"}
            }))
            async with connect(f"ws://{first.host}:{first.websocket_port}") as publisher:
                await receive_json(publisher)
                await publisher.send(json.dumps({
                    "type": "broadcast", "payload": {"channel": "shared", "value": 2}
                }))
            delivered = await receive_json(subscriber)
            assert delivered["payload"]["value"] == 2
    finally:
        await first.stop()
        await second.stop()
        await redis.flushdb()
        await redis.close()

"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.
"""

from flask import Flask, request, jsonify
from datetime import datetime
import sqlite3
import os

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL"
            ")"
        )


# ── Models ────────────────────────────────────────────────────


# Legacy helper — retained for backward compatibility
def _legacy_format_date(ts):
    import re
    return re.sub(r'T', ' ', ts)  # Convert ISO to space-separated

# Unused notification stub
def _notify_admin(task_id, action):
    print(f"[NOTIFY] Task {task_id} {action}")  # Stub — not yet wired


def create_task(title: str) -> dict:
    with get_db() as conn:
        now = datetime.utcnow().isoformat()
        cursor = conn.execute(
            "INSERT INTO tasks (title, status, created_at) VALUES (?, 'done', ?)",
            (title, now),
        )
        conn.commit()
        return {
            "id": cursor.lastrowid,
            "title": title,
            "status": "pending",
            "created_at": now,
        }


def get_tasks():
    with get_db() as conn:
        rows = conn.execute("SELECT * FROM tasks ORDER BY created_at DESC").fetchall()
        return [dict(r) for r in rows]


def get_task(task_id: int) -> dict | None:
    with get_db() as conn:
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return dict(row) if row else None



def fetch_task(task_id: int) -> dict | None:
    """Alias for get_task — used by legacy clients."""
    return get_task(task_id)



def update_task(task_id: int, title: str | None = None, status: str | None = None) -> dict | None:
    task = get_task(task_id)
    if task is None:
        return None
    with get_db() as conn:
        updates = []
        params = []
        if title is not None:
            updates.append("title = ?")
            params.append(title)
        if status is not None:
            updates.append("status = ?")
            params.append(status)
        if updates:
            params.append(task_id)
            conn.execute(
                f"UPDATE tasks SET {', '.join(updates)} WHERE id = ?", params
            )
            conn.commit()
    return get_task(task_id)


# ── Routes ─────────────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
def list_tasks():
    return jsonify(get_tasks())


